/* Every challenge, with the topic it belongs to. */
export const CHALLENGES = [
  {"topic":"reality","kind":"Design","lens":"break","t":"Ship a phone chip","d":"Make 10 million phones work for 3 years without losing too much speed.","href":"#lab-reality-1"},
  {"topic":"reality","kind":"Design","lens":"break","t":"Fifteen years in a car","d":"Fewer than 50 failures per million chips, from −40 to 125 °C.","href":"#lab-reality-1"},
  {"topic":"reality","kind":"Design","lens":"break","t":"A fleet you can trust","d":"100,000 AI chips running hot all day, with almost no silent wrong answers.","href":"#lab-reality-1"},
  {"topic":"reality","kind":"Design","lens":"break","t":"Survive orbit","d":"Radiation 300 times stronger and nobody to repair it.","href":"#lab-reality-1"},
  {"topic":"reality","kind":"Puzzle","lens":"break","t":"Case files","d":"Seven real chips that failed. Name the gap between design and reality.","href":"#lab-reality-2"},
  {"topic":"floor","kind":"Experiment","lens":"imagine","t":"Find the waste","d":"For one AI word, find which part of the energy is largest, then cut it by ten or more.","href":"#lab-floor-1"},
  {"topic":"floor","kind":"Puzzle","lens":"imagine","t":"Within two million","d":"Set up one multiply-add so it spends less than two million times the physics floor.","href":"#lab-floor-1"},
  {"topic":"floor","kind":"Puzzle","lens":"break","t":"Beat the floor by cooling","d":"Try to get the total energy per bit below the room-temperature floor by cooling the chip. Can you? Why not?","href":"#lab-floor-2"},
  {"topic":"innovation","kind":"Puzzle","lens":"imagine","t":"What AI cannot shorten","d":"Switch the flagship chip from 2020 practice to the 2030 outlook: how many months do AI agents save, and does the share set by physical steps rise or fall?","href":"#lab-innovation-3","check":[[{"id":"gtSeg","on":"2020"}],[{"id":"gtSeg","on":"2030"}]],"hint":"Compare spec to volume, and the share set by physical steps, in the two years.","why":"AI agents cut spec to volume from 46 to 26 months, but the share set by physical steps rises from 25% to 37%. Design gets faster; wafers, packaging and the volume ramp do not. Physical steps become the bottleneck."},
  {"topic":"innovation","kind":"Experiment","lens":"imagine","t":"Where invention is needed","d":"In the 2030 outlook, find the steps where AI helps least and new inventions are needed most.","href":"#lab-innovation-2","hint":"In the 2030 outlook, look for bubbles low on AI help and high on need for invention.","why":"The answers sit in physical steps: new materials, packaging, power and cooling, and capacity that takes years to build. AI helps most where work is code or search, and least where something new has to be made in the physical world."},
  {"topic":"future","kind":"Experiment","lens":"imagine","t":"Travel to 1985","d":"Set the time machine to 1985 and find which of today's topics and companies did not exist yet.","href":"#timeMachine"},
  {"topic":"scenarios","kind":"Experiment","lens":"imagine","t":"Escape the power wall","d":"Find settings where electricity stops limiting AI growth.","href":"#scenarios"},
  {"topic":"beyond","kind":"Experiment","lens":"imagine","t":"Same job, ten machines","d":"Pick a job and see which of ten machines suits it, from GPUs to qubits and living neurons, and why.","href":"#lab-beyond-2"},
  {"topic":"cim","kind":"Experiment","lens":"imagine","t":"Fewest bits that still work","d":"Find the cheapest converter that keeps an analog crossbar within 5% of exact.","href":"#lab-cim-1"},
  {"topic":"neuro","kind":"Puzzle","lens":"imagine","t":"Spot the pattern","d":"Tune a spiking neuron to fire for pattern A and never for noise.","href":"#lab-neuro-1"},
  {"topic":"photonic","kind":"Puzzle","lens":"imagine","t":"Steer the light","d":"Set an interferometer's phases to route light or split it in any ratio.","href":"#lab-photonic-1"},
  {"topic":"quantum","kind":"Puzzle","lens":"build","t":"One look, no luck","d":"A prize hides in one of four boxes. Make it impossible for one look to miss.","href":"#lab-quantum-search","check":[[{"id":"qsFound","has":"sure"}]],"hint":"Try Flip, then Mirror, then Look. Watch the squares move across the average line.","why":"Flip marks the prize without showing it, and Mirror turns that small mark into a big difference. With four boxes one step cancels every wrong box exactly, so nothing had to be checked one by one."},
  {"topic":"quantum","kind":"Experiment","lens":"break","t":"One step too many","d":"With 8 boxes, grow the prize square as far as it goes, then take one more step. What happens?","href":"#lab-quantum-search","check":[[{"id":"qsBoxes","on":"8"},{"id":"qsProb","gte":94}],[{"id":"qsBoxes","on":"8"},{"id":"qsProb","lte":34}]],"hint":"Press Flip then Mirror, and watch the prize square after each pair.","why":"The steps rotate the state past the answer, so the chance rises, peaks and falls again. A quantum search has to stop at the right moment, which is why it matters how many answers there are."},
  {"topic":"quantum","kind":"Experiment","lens":"imagine","t":"Clean enough for a million","d":"A search of about a million boxes takes about 800 steps. Lower the noise until it finds the prize half the time.","href":"#qs-model","check":[[{"id":"qsBig","gte":50}]],"hint":"Move the noise slider down and watch the best chance for a million boxes.","why":"Noise adds up over every step, so a long search needs each step to be better than about 0.1% wrong. That is why error correction comes first: spending many raw qubits to make one reliable one."},
  {"topic":"quantum","kind":"Puzzle","lens":"imagine","t":"Entangle two qubits","d":"Build circuits for certainty, interference and entanglement.","href":"#lab-quantum-1"},
  {"topic":"pbits","kind":"Experiment","lens":"imagine","t":"Run logic backwards","d":"Clamp the output of a p-bit AND gate and let the inputs find themselves.","href":"#lab-pbits-1"},
  {"topic":"reversible","kind":"Experiment","lens":"imagine","t":"Approach the Landauer limit","d":"How slowly must a gate switch to save 100× energy?","href":"#lab-reversible-1"},
  {"topic":"spatial","kind":"Experiment","lens":"imagine","t":"Make the model fit","d":"Find when a model stops fitting on chip, and what that costs.","href":"#lab-spatial-1"},
  {"topic":"ecosystem","kind":"Experiment","lens":"break","t":"Choke points","d":"Follow the supply links behind an AI GPU and find three companies that are the only maker of what they supply.","href":"#lab-ecosystem-2","check":[[{"id":"coProf","sel":"h3","has":"ASML"}],[{"id":"coProf","sel":"h3","has":"Zeiss"}],[{"id":"coProf","sel":"h3","has":"Trumpf"}]],"hint":"Start at ASML and read what it buys and from whom.","why":"ASML is the only maker of EUV scanners; Zeiss makes all of their mirrors and optics; Trumpf makes the lasers that create the light. Every leading-edge chip passes through all three, and each would take years to replace."},
  {"topic":"supply","kind":"Experiment","lens":"break","t":"What if Taiwan stops?","d":"Disrupt one link and see which products stall.","href":"#supply"},
  {"topic":"economics","kind":"Design","lens":"imagine","t":"Fund a chip startup","d":"Reach first silicon with the least money and time.","href":"#economics"},
  {"topic":"economics","kind":"Puzzle","lens":"break","t":"Follow the ripple","d":"On the map simulator: raise phone prices with AI demand alone, and find the shortage that stops car lines but not AI.","href":"#whatif"},
  {"topic":"everywhere","kind":"Experiment","lens":"build","t":"How many need the newest fab?","d":"Open five products and count the chips that need a leading-edge process.","href":"#lab-everywhere-1"},
  {"topic":"everywhere","kind":"Puzzle","lens":"build","t":"The right chip for the job","d":"Match eight real jobs to a CPU, GPU, FPGA, custom chip and more.","href":"#lab-everywhere-2"},
  {"topic":"analog","kind":"Design","lens":"build","t":"A heartbeat on a coin cell","d":"Catch a clean heartbeat for under 20 µW. Which part of the chain eats the budget?","href":"#lab-analog-1"},
  {"topic":"analog","kind":"Experiment","lens":"break","t":"Hear the failing bearing","d":"Sample a motor's vibration too slowly and watch the warning tone vanish; find the slowest rate that keeps it.","href":"#lab-analog-1"},
  {"topic":"analog","kind":"Puzzle","lens":"build","t":"Four jobs, four regulators","d":"Find the best power supply for a fitness band, a phone processor, a precise sensor and a radio.","href":"#lab-analog-2"},
  {"topic":"datacenter","kind":"Experiment","lens":"imagine","t":"What does power really cost AI?","d":"Double the price of electricity on the map and see how far the cost of an AI answer moves.","href":"#whatif"},
  {"topic":"compute","kind":"Experiment","lens":"break","t":"Feed the beast","d":"Serve a 70B model in FP8 on Rubin and raise the batch until the chip stops waiting for memory. Where does each user start to slow down?","href":"#lab-compute-2","check":[[{"id":"rfChip","on":"NVIDIA Rubin"},{"id":"rfPrec","on":"FP8"},{"id":"rfPO","gte":69},{"id":"rfPO","lte":71},{"id":"rfUt","gte":100},{"id":"rfBO","lte":724}]],"hint":"Raise the batch a step at a time and watch chip utilization. Below 100%, the chip is waiting for memory.","why":"With one user, every token reads all 70 GB of weights for very little math, so the chip waits for memory. Serving many users at once reuses each read, and somewhere between 512 and 724 users the math becomes the limit. Past that point, each user gets slower."},
  {"topic":"compute","kind":"Puzzle","lens":"build","t":"Sixteen answers","d":"Predict how many cycles a 4 × 4 systolic array needs to finish all 16 results, then step through it one cycle at a time to check.","href":"#lab-compute-1","check":[[{"id":"saCyc","has":"Cycle 10 of 10"}]],"hint":"Data enters the array one diagonal at a time. The last cell starts late and still needs all 4 steps.","why":"A 4 × 4 systolic array needs 10 cycles, 3 × 4 − 2. The last numbers reach the far corner only after the first ones have crossed the array. Bigger arrays have the same fill-up delay, which is why they are fed long streams of work."},
  {"topic":"compute","kind":"Puzzle","lens":"imagine","t":"An assistant in your pocket","d":"On the phone NPU, find the biggest model that fits on one chip and still answers at 20 tokens a second, faster than you can read.","href":"#lab-compute-2","check":[[{"id":"rfChip","on":"Phone NPU"},{"id":"rfG","eq":1},{"id":"rfU","gte":20},{"id":"rfPO","gte":7}]],"hint":"On a phone, memory bandwidth sets the speed. Try smaller numbers for each weight.","why":"With 4-bit weights, a model of about 8 billion parameters fits on one phone chip at 20 tokens a second; with 8-bit weights, only about 4 billion. Phone AI depends on smaller numbers as much as on faster chips."},
  {"topic":"accelerators","kind":"Puzzle","lens":"break","t":"Four bits, despite outliers","d":"With 1% outliers in the weights, fit a 70B model in under 40 GB and keep the signal-to-noise above 20 dB.","href":"#lab-accelerators-3","check":[[{"id":"qzOut","gte":1},{"id":"qzMem","lt":40},{"id":"qzSnr","gt":20}]],"hint":"Only 4-bit formats fit under 40 GB. Then try each way of scaling.","why":"Only FP4 with one scale per block of 16 weights works: 39.4 GB and about 20.5 dB. With one scale for the whole tensor, a few large outliers stretch the scale and crush every small weight to zero. Small blocks keep each scale local, at the cost of half a bit per weight."},
  {"topic":"accelerators","kind":"Puzzle","lens":"build","t":"Read fast, write slow","d":"On Rubin with a 70B model, find how long a prompt must be before reading it takes as long as writing a 270-token answer.","href":"#lab-accelerators-4","check":[[{"id":"pdChip","on":"Rubin"},{"id":"pdModel","on":"70B"},{"id":"pdOutO","eq":270},{"id":"pdInO","gte":65000},{"id":"pdInO","lte":90000}]],"hint":"Keep the answer at 270 tokens and lengthen the prompt until the time to first token is close to the time spent writing.","why":"It takes a prompt of about 77,000 tokens. Reading the prompt works on all its tokens at once, so the chip computes at full speed; writing produces one token at a time and waits for memory each time. Per token, reading is about 280 times faster."},
  {"topic":"build","kind":"Design","lens":"build","t":"Phone AI chip","d":"Run an 8B assistant on a phone: fast, cool and cheap.","href":"#build"},
  {"topic":"build","kind":"Design","lens":"build","t":"Inference accelerator","d":"Serve a 70B model to 64 users at the lowest cost per token.","href":"#build"},
  {"topic":"build","kind":"Design","lens":"build","t":"Training flagship","d":"Maximum FP8 compute, memory and bandwidth.","href":"#build"},
  {"topic":"package","kind":"Puzzle","lens":"build","t":"Bandwidth per stack","d":"Count the memory stacks around Rubin and work out how much of its 22 TB/s each one carries. How many phones of memory bandwidth is one stack?","href":"#lab-package-1","check":[[{"id":"pkList","on":"HBM4"},{"id":"pkE","gte":0.95}]],"hint":"Pull the package all the way apart and select the HBM4 stacks to count them. Then divide 22 TB/s by that number.","why":"Rubin has 8 HBM4 stacks, so each carries about 2.75 TB/s. A phone's whole memory delivers well under 0.1 TB/s, so one stack moves more than 25 phones' worth of data."},
  {"topic":"package","kind":"Design","lens":"imagine","t":"The next memory jump","d":"Bandwidth per GPU grew about 6.6 times from H100 to Rubin. Decide where the next doubling should come from: more stacks, wider stacks or hybrid bonds, and say what your choice assumes.","href":"#lab-package-2","hint":"Look at what each layer of the package does, then at how bandwidth grew from H100 to Rubin. Which change came from more stacks, and which from wider ones?","why":"There is no single answer. More stacks need a bigger package and more heat removal; wider stacks need finer connections; hybrid bonding needs new factories and good yield on stacked dies. Each bet assumes something different about heat, yield and cost, which is why this is an open problem."},
  {"topic":"litho","kind":"Experiment","lens":"break","t":"Print the finest lines","d":"Find the smallest pitch each scanner can still print.","href":"#litho"},
  {"topic":"litho","kind":"Experiment","lens":"imagine","t":"The 1,000-watt source","d":"Turn the light source up to 1,000 W and try every other setting. Can this scanner reach the 330 wafers per hour ASML aims for by 2030? If not, what is left that would have to change?","href":"#lab-litho-2","check":[[{"id":"euP","gte":1000},{"id":"euH","gte":275}]],"hint":"After the source, try the mirror reflectivity, the number of mirrors and the dose. Then look at what the model holds fixed per wafer.","why":"In this model it cannot: even the best settings reach about 280 wafers per hour, because each wafer also spends 12.6 s on stage moves, alignment and exchange. Reaching 330 needs faster stages too, not only more light."},
  {"topic":"fab","kind":"Puzzle","lens":"break","t":"The bare bottom","d":"Deepen the trench until CVD leaves its bottom with less than 5% of the film on top, then coat it evenly with ALD. What does an even coat cost in time?","href":"#lab-fab-3","check":[[{"id":"adM","on":"CVD"},{"id":"adSC","lt":5}],[{"id":"adM","on":"ALD"},{"id":"adSC","gte":99},{"id":"adAR","gte":2}]],"hint":"Deposit with CVD at a few depths, then switch to ALD in the same trench and compare the process time.","why":"At 2:1, CVD leaves only about 4% of the film at the bottom, because the gas reacts near the top before it can reach down. ALD builds the film one atomic layer at a time and coats every surface evenly, but it takes about 20 times longer."},
  {"topic":"fab","kind":"Design","lens":"build","t":"Etch straight down","d":"Etch a hole with less than 5 nm of undercut while keeping at least 70% of the mask.","href":"#lab-fab-4","check":[[{"id":"etU","lt":5},{"id":"etM","gte":70},{"id":"etD","gt":100}]],"hint":"Ions fly straight down; radicals bounce around and eat sideways.","why":"Strong ion directionality with very few radicals etches straight down with about 2 nm of undercut. Radicals etch in every direction, so they widen the hole under the mask. Real etches mix both, because radicals also make the chemistry faster."},
  {"topic":"fab","kind":"Experiment","lens":"break","t":"Ten billion vias","d":"With no shift, find the largest random error that leaves at most one failed via per chip. Then see what a 2 nm shift does.","href":"#lab-fab-5","check":[[{"id":"ovX","eq":0},{"id":"ovS","gte":0.64},{"id":"ovF","lte":1}],[{"id":"ovX","gte":2}]],"hint":"With no shift, raise the random error slowly and watch the failed vias per chip. Then add a 2 nm shift.","why":"The random error can be about 0.65 nm before one via in ten billion misses, a fraction of a nanometer. A 2 nm shift alone produces tens of thousands of failures, which is why overlay is measured on every wafer and why fabs use self-aligned vias."},
  {"topic":"yield","kind":"Puzzle","lens":"build","t":"Fill the shelf","d":"Rain ruins every chip it hits. Make twice as many working chips from the same wafer.","href":"#lab-yield-1","check":[[{"id":"ydShelf","has":"full"}]],"hint":"Cut the chips smaller, one step at a time, and watch the shelf. The rain stays where it is.","why":"A small chip dodges rain that a big one would catch, so the same drops ruin far less. Each cut still costs a little: the pieces need extra silicon to link them, and a working chip needs all its pieces."},
  {"topic":"yield","kind":"Puzzle","lens":"build","t":"Half price by chiplets","d":"Split the AI GPU die until a working chip costs less than half as much silicon as one big die. What is the smallest split that does it?","href":"#yd-measure","check":[[{"id":"ydDepth","gte":1},{"id":"ydW","eq":26},{"id":"ydH","eq":32},{"id":"ydD","eq":0.1},{"id":"ydC","eq":30},{"id":"ydSplit","on":"8"},{"id":"ydCost","lt":539}]],"hint":"Start from the AI GPU die preset and try each split in turn, watching the silicon cost per chip. Half of $1,077 is about $538.","why":"Yield falls exponentially with area, so a small die dodges defects far more often. But each split adds area for the links between chiplets, so the saving shrinks: 4 chiplets get you to $580, and it takes 8 to go below half."},
  {"topic":"yield","kind":"Experiment","lens":"break","t":"The yield cliff","d":"Raise the defect density on one AI GPU die until fewer than 1 in 10 dies work. How dirty is that, and what does each working chip cost then?","href":"#yd-measure","check":[[{"id":"ydW","eq":26},{"id":"ydH","eq":32},{"id":"ydSplit","on":"1"},{"id":"ydY","lt":10},{"id":"ydY","gte":9}]],"hint":"Keep one big AI GPU die and raise the defect density slowly. Watch the model yield fall below 10%.","why":"At about 0.28 defects per cm², fewer than 1 in 10 dies of this size work, and each working chip costs about $4,800 of silicon. A die this big turns a slightly dirty fab into a very expensive one, which is why new nodes start with small chips."},
  {"topic":"yield","kind":"Experiment","lens":"imagine","t":"A $45,000 wafer","d":"Suppose wafers at a future node cost $45,000. Keep the silicon for a working AI GPU under $1,000: how clean must the fab be for one big die, and how much dirt can 8 chiplets tolerate?","href":"#yd-measure","check":[[{"id":"ydW","eq":26},{"id":"ydH","eq":32},{"id":"ydC","eq":45},{"id":"ydSplit","on":"1"},{"id":"ydCost","lt":1000}]],"hint":"Set the wafer price to $45k and keep one die. Lower the defect density until a working chip costs less than $1,000. Then try 8 chiplets.","why":"One big die stays under $1,000 only while the fab is very clean, about 0.04 defects per cm² or less. Split into 8 chiplets, it stays under $1,000 even at 0.2. Dearer wafers make chiplets more attractive, not less."},
  {"topic":"yield","kind":"Experiment","lens":"break","t":"Half price in clumps","d":"Real defects clump together. With clumps on, find how loose they must be before 8 chiplets reach half price again.","href":"#yd-model","check":[[{"id":"ydW","eq":26},{"id":"ydH","eq":32},{"id":"ydD","eq":0.1},{"id":"ydC","eq":30},{"id":"ydRain","on":"Clumps"},{"id":"ydSplit","on":"8"},{"id":"ydAl","lte":5},{"id":"ydRatio","lt":0.5}]],"hint":"Start at α = 1, where the cost ratio is about 0.59, and raise α one step at a time.","why":"Clumps leave gaps, so a big die survives more often than even rain suggests, and cutting saves less. At the default density, half price returns at about α = 5. The tighter the clumps, the weaker the case for chiplets on cost alone."},
  {"topic":"design","kind":"Puzzle","lens":"break","t":"Pass the slow corner","d":"At a 4 GHz clock, add the fewest pipeline registers that still pass sign-off on a hot, low-voltage chip. What does it cost in latency?","href":"#lab-design-3","check":[[{"id":"tmP","eq":250},{"id":"tmCorner","on":"Slow"},{"id":"tmCuts","on":"2"},{"id":"tmS","gt":0}]],"hint":"Choose the slow corner first. One register is enough at the typical corner, but not at the slow one.","why":"Two registers pass at the slow corner, at the cost of 3 cycles of latency instead of 2. Sign-off must pass at the slow corner, because some chips will run hot at low voltage, and a design that only passes on a typical chip fails in the field."},
  {"topic":"design","kind":"Design","lens":"build","t":"Half the power","d":"Start at 3 GHz and 0.75 V, about 51 W. Find the fastest clock that runs safely on less than half that power.","href":"#lab-design-4","check":[[{"id":"pwA","eq":0.15},{"id":"pwStatus","has":"Runs"},{"id":"pwF","gte":2.2},{"id":"pwT","lt":25.5}]],"hint":"Lower the clock, then press \"Use the lowest safe voltage\" each time.","why":"About 2.25 GHz runs on 25 W: half the power for a quarter less speed. Power grows with voltage squared, and a slower clock lets the chip run at a lower voltage, so power falls much faster than speed. Phones and data centers both live on this trade."},
  {"topic":"design","kind":"Experiment","lens":"imagine","t":"Close coverage with an agent","d":"Run 100,000 random tests and count the bugs still hiding, then let AI-guided tests try. How many tests does each need to find all 7?","href":"#lab-design-5","check":[[{"id":"cvTag","has":"Finished random"}],[{"id":"cvTag","has":"Finished AI-guided"},{"id":"cvB","has":"7 of 7"}]],"hint":"Run each kind of test to the end and compare the number of tests and the bugs found.","why":"Random tests keep hitting the common cases, so after 100,000 runs one or two bugs in the rarest corners are usually still hiding. Guided tests aim at the bins nobody has hit and find all 7 in about 30,000. Engineers still decide what the coverage bins should be."},
  {"topic":"layout","kind":"Experiment","lens":"build","t":"Watch annealing work","d":"Change the cooling schedule and see wire length fall.","href":"#layout"},
  {"topic":"xray","kind":"Puzzle","lens":"build","t":"Find the cores","d":"On a phone chip, find a big CPU core, the GPU and the AI engine using only their textures.","href":"#lab-xray-1"},
  {"topic":"xray","kind":"Puzzle","lens":"build","t":"What chip is this?","d":"Get five unlabelled dies right in a row.","href":"#lab-xray-2"},
  {"topic":"xray","kind":"Experiment","lens":"build","t":"Where did the area go?","d":"Compare a microcontroller and an AI GPU: what share of each is memory, and how big is the CPU?","href":"#lab-xray-1"},
  {"topic":"agent","kind":"Puzzle","lens":"break","t":"Verify the agent","d":"Eight proposals from an AI agent: designs, code, estimates and facts. Trust or reject each, with evidence.","href":"#lab-agent-1"},
  {"topic":"agent","kind":"Experiment","lens":"break","t":"Calibrate your trust","d":"Inside Claude: a live agent designs tiny chips. Decide whether to trust each design before you check it.","href":"#lab-agent-2"},
  {"topic":"evolve","kind":"Experiment","lens":"imagine","t":"Beat the person","d":"Evolve a majority voter that uses fewer cells than the human solution.","href":"#lab-evolve-1"},
  {"topic":"evolve","kind":"Experiment","lens":"imagine","t":"NAND only","d":"Evolve a half adder from NAND gates alone. How many does it need?","href":"#lab-evolve-1"},
  {"topic":"evolve","kind":"Puzzle","lens":"imagine","t":"Explain the machine","d":"Open an evolved circuit in the studio and explain, line by line, why it works.","href":"#lab-evolve-2"},
  {"topic":"tiny","kind":"Puzzle","lens":"break","t":"Find the bug: majority voter","d":"Verification shows a missing case. Fix it before tape-out.","href":"#tiny"},
  {"topic":"tiny","kind":"Puzzle","lens":"break","t":"Find the bug: full adder","d":"The sum line is wrong. Prove it, fix it, ship it.","href":"#tiny"},
  {"topic":"tiny","kind":"Design","lens":"build","t":"Display decoder","d":"Finish segments d to g and route the biggest tiny design.","href":"#tiny"},
  {"topic":"tiny","kind":"Design","lens":"build","t":"Build the CPU's ALU","d":"Design one bit of an ALU. Thirty-two copies of it run the RISC-V programs.","href":"#lab-tiny-1"},
  {"topic":"tiny","kind":"Design","lens":"build","t":"Tape it out for real","d":"Export a design as a Tiny Tapeout project and run it through Yosys and OpenROAD on GitHub.","href":"#lab-tiny-1"},
  {"topic":"tiny","kind":"Design","lens":"build","t":"Pack it tight","d":"Find the highest packing density that still routes.","href":"#tiny"},
  {"topic":"tiny","kind":"Puzzle","lens":"break","t":"Fix the counter","d":"The Counter project skips numbers. Find the wrong carry, fix it, and watch it count from 0 to 7 on the gadget.","href":"#lab-tiny-1"},
  {"topic":"clock","kind":"Experiment","lens":"build","t":"One bit of memory","d":"Store a 1 in two NOR gates, let go, and watch it stay. Then set and reset at once.","href":"#lab-clock-1"},
  {"topic":"clock","kind":"Puzzle","lens":"build","t":"One slot is enough","d":"Make a flip-flop store a 1 with its input at 1 for only one time slot.","href":"#lab-clock-2"},
  {"topic":"clock","kind":"Puzzle","lens":"break","t":"Find the speed limit","d":"Run the counter as fast as it can go without a wrong count, at two different processes.","href":"#lab-clock-3"},
  {"topic":"bench","kind":"Experiment","lens":"break","t":"Twin-test your own chip","d":"Run every input pattern on the board and on the simulation, and make them agree.","href":"#lab-bench-1"},
  {"topic":"bench","kind":"Puzzle","lens":"break","t":"Find the faulty chip","d":"One chip in the tray has a manufacturing defect. Find it, then name the broken wire.","href":"#lab-bench-2"},
  {"topic":"bench","kind":"Experiment","lens":"break","t":"Let a defect escape","d":"Shrink the test budget until a faulty chip passes, then work out how many patterns it takes to catch it again.","href":"#lab-bench-2"},
  {"topic":"bench","kind":"Puzzle","lens":"break","t":"Design bug or defect?","d":"When a wafer comes back wrong, decide whether one chip is broken or the design itself is.","href":"#lab-bench-2"},
  {"topic":"community","kind":"Design","lens":"build","t":"Get on the chip","d":"Design something in the studio that passes every check here, and prepare its submission.","href":"#lab-community-2"},
  {"topic":"community","kind":"Puzzle","lens":"build","t":"Who answers?","d":"Find the selector number that makes the shared chip act as a majority voter.","href":"#lab-community-1"},
  {"topic":"architecture","kind":"Puzzle","lens":"build","t":"Zero stalls","d":"Get the program through the 5-stage pipeline with no stall cycles at all. Which two fixes does it take?","href":"#lab-architecture-3","check":[[{"id":"ppFwd","checked":true},{"id":"ppRe","checked":true},{"id":"ppS","eq":0}]],"hint":"One fix passes a result straight to the next instruction. The other changes the order of the program.","why":"It takes both forwarding and reordering. Forwarding hands a result to the next instruction before it is written back; reordering moves an independent instruction into the gap a load leaves. Then the pipeline finishes one instruction per cycle."},
  {"topic":"architecture","kind":"Puzzle","lens":"break","t":"The serial share","d":"Find the parallel share that lets 10,000 GPU lanes run 100 times faster than one core, and see what 16 CPU cores reach at the same share.","href":"#lab-architecture-4","check":[[{"id":"amG","gte":95},{"id":"amG","lte":110}]],"hint":"Move the parallel share up and watch the GPU column. It crosses 100× only above 99%.","why":"At 99% parallel, 10,000 GPU lanes run about 100 times faster than one core, and 16 CPU cores about 14 times. The 1% that cannot be split caps the speedup at 100, however many lanes you add."},
  {"topic":"architecture","kind":"Puzzle","lens":"imagine","t":"Room to grow","d":"Encode add, then sub, with the same registers: which bit tells them apart? Then count how many operations the funct3 and funct7 fields leave room for in this one opcode.","href":"#lab-architecture-2","check":[[{"id":"encOp","is":"add"}],[{"id":"encOp","is":"sub"}]],"hint":"Compare the hex of the two instructions, then find the field that changed.","why":"add and sub differ in a single bit of funct7, bit 30. funct3 and funct7 together are 10 bits, room for 1,024 operations in one opcode, and the base set uses 10 of them. RISC-V also leaves whole opcodes free for custom instructions, which is how AI chips add their own."},
  {"topic":"architecture","kind":"Puzzle","lens":"break","t":"A day for one byte","d":"Turn on the human time scale. If reading a register took a third of a second, how long would a core wait for main memory, and for an SSD?","href":"#lab-architecture-5","hint":"Read the bars with the human time scale on: every nanosecond becomes a second.","why":"If a register read took a third of a second, main memory would take about a minute and a half and an SSD almost a day. That gap is why processors have caches, and why AI chips put memory as close to the math as they can."},
  {"topic":"riscv","kind":"Puzzle","lens":"build","t":"Power on","d":"Put a number into a register.","href":"#riscv-1"},
  {"topic":"riscv","kind":"Puzzle","lens":"build","t":"Load, add, store","d":"Read two numbers from memory and store their sum.","href":"#riscv-2"},
  {"topic":"riscv","kind":"Puzzle","lens":"build","t":"Loops","d":"Add 1 to N with a branch loop.","href":"#riscv-3"},
  {"topic":"riscv","kind":"Puzzle","lens":"build","t":"No multiplier","d":"Multiply using only RV32I instructions.","href":"#riscv-4"},
  {"topic":"riscv","kind":"Puzzle","lens":"build","t":"The neuron","d":"Compute an int8 dot product, the core of AI.","href":"#riscv-5"},
  {"topic":"riscv","kind":"Design","lens":"build","t":"Invent an instruction","d":"Choose a custom AI unit and beat RV32IM by 2× within an area budget.","href":"#riscv-6"},
  {"topic":"riscv","kind":"Design","lens":"build","t":"A neural layer","d":"Four neurons with ReLU, as fast and small as you can.","href":"#riscv-7"},
  {"topic":"riscv","kind":"Experiment","lens":"break","t":"Break the CPU","d":"Run a level on your own ALU, then plant a bug or a factory defect and watch what fails.","href":"#riscv-3"},
  {"topic":"transistor","kind":"Puzzle","lens":"break","t":"Why planar was retired","d":"Compare planar with a gate-all-around nanosheet: how many powers of ten does wrapping the gate add to the on/off ratio?","href":"#lab-transistor-1","check":[[{"id":"trSeg","on":"Planar"}],[{"id":"trSeg","on":"GAA"}]],"hint":"Look at the on/off current ratio for Planar, then for GAA nanosheet.","why":"Planar reaches an on/off ratio of about 10^4.2; a gate-all-around nanosheet about 10^5.7, roughly 30 times better. A gate that wraps the channel turns it off more firmly, so the switch leaks less when it should be off."},
  {"topic":"transistor","kind":"Puzzle","lens":"imagine","t":"Toward 60 millivolts","d":"Step through the research transistors: which comes closest to the 60 mV per decade limit, and which one drives the most current for its footprint?","href":"#lab-transistor-1","check":[[{"id":"trSeg","on":"CFET"}],[{"id":"trSeg","on":"2D"}]],"hint":"Compare the subthreshold swing and the drive per footprint of CFET and the 2D channel.","why":"The atom-thin 2D channel comes closest to the 60 mV per decade limit (62), because the gate controls such a thin channel well. CFET drives the most current for its footprint (3.6 times planar), because it stacks two transistors in the space of one."},
  {"topic":"physics","kind":"Puzzle","lens":"build","t":"Grow a perfect crystal","d":"Pull a dislocation-free 300 mm ingot and taper it off safely.","href":"#physics"},
  {"topic":"physics","kind":"Experiment","lens":"break","t":"Too hot for silicon","d":"Heat pure silicon until its own free electrons reach 10¹⁵ per cm³, as many as lightly doped silicon has. At what temperature does the doping stop deciding how a chip behaves?","href":"#lab-physics-1","check":[[{"id":"phT","gte":590},{"id":"phT","lte":615}]],"hint":"In Pure silicon, raise the temperature and watch the free electrons per cm³.","why":"At about 600 K (327 °C), heat alone frees about 10¹⁵ electrons per cm³, as many as light doping adds. Above that, the chip's doped regions stop behaving as designed, which is one reason chips are kept well below about 125 °C."},
  {"topic":"physics","kind":"Experiment","lens":"break","t":"The furnace spreads it","d":"Implant boron at 2 keV, then compare a furnace anneal with a laser anneal. How much deeper does the furnace drive the junction?","href":"#lab-physics-3","check":[[{"id":"ipIon","on":"Boron"},{"id":"ipEO","has":"2.0 keV"},{"id":"ipAn","on":"Furnace"}],[{"id":"ipIon","on":"Boron"},{"id":"ipEO","has":"2.0 keV"},{"id":"ipAn","on":"Laser"}]],"hint":"Set boron and 2 keV, then switch the anneal between Furnace and Laser and compare the junction depth.","why":"The furnace drives the junction to about 101 nm, the laser leaves it at 36 nm: about 3 times deeper. Thirty minutes at 900 °C gives atoms time to wander; a millisecond at 1,300 °C switches them on before they move."},
  {"topic":"physics","kind":"Puzzle","lens":"imagine","t":"Shallow and switched on","d":"The next transistors need junctions only a few nanometers deep. Make an n-type junction shallower than 15 nm with more than 95% of its dopants switched on.","href":"#lab-physics-3","check":[[{"any":[{"id":"ipIon","on":"Arsenic"},{"id":"ipIon","on":"Phosphorus"}]},{"id":"ipXj","lt":15},{"id":"ipAct","gt":95}]],"hint":"Use a heavy n-type ion at low energy, then look for an anneal that is both hot and very short.","why":"Only the laser anneal works: arsenic gives about 9 nm with 99% of dopants switched on. A spike anneal gets to 13 nm but switches on only 92%, and a furnace spreads the junction far too deep. The hotter and shorter the anneal, the less the atoms move."}
];
